import os, time
import numpy as np
try:
    from scipy.optimize import minimize
except Exception:
    minimize = None

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

SNAP_CENTERS = 'storage/noesis/latest_centers.txt'
SNAP_RADII   = 'storage/noesis/latest_radii.txt'

# ---------- Helpers: pack/unpack ----------
def _pack_to_z(c, r):
    Z = np.zeros((N, 3), dtype=float)
    Z[:, :2] = c
    Z[:, 2] = r
    return Z.ravel()

def _z_to_pack(z):
    Z = np.array(z, dtype=float).reshape(N, 3)
    return Z[:, :2], Z[:, 2]

# ---------- Constraints (ineq >= 0) ----------
def ineq_boundary(z):
    Z = np.array(z, dtype=float).reshape(N, 3)
    x = Z[:, 0]; y = Z[:, 1]; r = Z[:, 2]
    return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

def jac_boundary(z):
    J = np.zeros((4*N, 3*N), dtype=float)
    for i in range(N):
        xi = 3*i; yi = xi + 1; ri = xi + 2
        J[i, xi] = 1.0;        J[i, ri] = -1.0        # x - r
        J[N + i, xi] = -1.0;   J[N + i, ri] = -1.0    # 1 - x - r
        J[2*N + i, yi] = 1.0;  J[2*N + i, ri] = -1.0  # y - r
        J[3*N + i, yi] = -1.0; J[3*N + i, ri] = -1.0  # 1 - y - r
    return J

def ineq_nonoverlap(z):
    Z = np.array(z, dtype=float).reshape(N, 3)
    C = Z[:, 0:2]; r = Z[:, 2]
    diff = C[:, None, :] - C[None, :, :]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    iu = np.triu_indices(N, 1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])

def jac_nonoverlap(z):
    Z = np.array(z, dtype=float).reshape(N, 3)
    C = Z[:, 0:2]
    m = N*(N-1)//2
    J = np.zeros((m, 3*N), dtype=float)
    idx = 0
    for i in range(N):
        xi = 3*i; yi = xi + 1; ri = xi + 2
        for j in range(i+1, N):
            xj = 3*j; yj = xj + 1; rj = xj + 2
            dx = C[i,0] - C[j,0]; dy = C[i,1] - C[j,1]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                gx_i = gy_i = gx_j = gy_j = 0.0
            else:
                invd = 1.0 / d
                gx_i = dx * invd; gy_i = dy * invd
                gx_j = -gx_i;     gy_j = -gy_i
            J[idx, xi] = gx_i;  J[idx, yi] = gy_i;  J[idx, ri] = -1.0
            J[idx, xj] = gx_j;  J[idx, yj] = gy_j;  J[idx, rj] = -1.0
            idx += 1
    return J

# ---------- Objective ----------
def objective(z):
    # Maximize sum(r) -> minimize -sum(r)
    return -np.sum(z[2::3])

def objective_jac(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g

# ---------- Feasibility guard (strict) ----------
def boundary_caps(centers, eps=SAFETY):
    x = centers[:, 0]; y = centers[:, 1]
    cap = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y)) - eps
    return np.maximum(cap, R_MIN)

def make_feasible(centers, radii, eps=SAFETY, max_iter=3000):
    n = centers.shape[0]
    r = np.minimum(radii, boundary_caps(centers, eps=eps))
    r = np.maximum(r, R_MIN)
    for _ in range(max_iter):
        diff = centers[:, None, :] - centers[None, :, :]
        dist = np.sqrt(np.sum(diff**2, axis=2)) + 1e-15
        iu = np.triu_indices(n, 1)
        m = dist[iu] - (r[iu[0]] + r[iu[1]])
        if np.all(m >= eps):
            break
        k = int(np.argmin(m))
        i = iu[0][k]; j = iu[1][k]
        need = (r[i] + r[j] - dist[i, j]) + eps
        di = min(need * 0.5, r[i] - R_MIN)
        dj = min(need - di, r[j] - R_MIN)
        if di <= 0 and dj <= 0:
            r = np.maximum(r * 0.999, R_MIN)
        else:
            r[i] -= di; r[j] -= dj
        r = np.minimum(r, boundary_caps(centers, eps=eps))
    return centers, np.maximum(r - SAFETY, R_MIN)

# ---------- Seeds ----------
def load_snapshot_or_fallback():
    try:
        c = np.loadtxt(SNAP_CENTERS, dtype=float).reshape(N, 2)
        r = np.loadtxt(SNAP_RADII, dtype=float).reshape(N,)
        if np.any(r <= 0):
            raise ValueError("non-positive r")
        return c, r
    except Exception:
        # conservative grid+hole fallback
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    x = 0.1 + i * 0.2
                    y = 0.1 + j * 0.15
                    centers.append([x, y])
        c = np.array(centers, dtype=float)
        r = np.full(N, radius, dtype=float)
        return c, r

def jitter_seed(c0, r0, rng, pos_sigma=2.0e-3, rad_scale=1.0e-3):
    c = c0 + rng.normal(0.0, pos_sigma, size=c0.shape)
    c = np.clip(c, 0.0, 1.0)
    r = np.maximum(r0 * (1.0 + rng.normal(0.0, rad_scale, size=r0.shape)), R_MIN)
    return make_feasible(c, r)

# ---------- Local optimize ----------
def local_optimize(c_seed, r_seed, maxiter=400, ftol=1e-9):
    if minimize is None:
        return make_feasible(c_seed, r_seed)
    z0 = _pack_to_z(c_seed, r_seed)
    cons = [
        {'type': 'ineq', 'fun': ineq_boundary,   'jac': jac_boundary},
        {'type': 'ineq', 'fun': ineq_nonoverlap, 'jac': jac_nonoverlap},
    ]
    bounds = []
    for _ in range(N):
        bounds.extend([(0.0, 1.0), (0.0, 1.0), (R_MIN, 0.5)])
    try:
        res = minimize(objective, z0, method='SLSQP', jac=objective_jac,
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
    except Exception:
        res = None
    if res is not None and res.success:
        c_opt, r_opt = _z_to_pack(res.x)
        return make_feasible(c_opt, r_opt)
    return make_feasible(c_seed, r_seed)

def score_r(r):
    return float(np.sum(r))

def construct_packing():
    start = time.time()
    rng = np.random.default_rng(1234567)

    # Base seed: snapshot
    c0, r0 = load_snapshot_or_fallback()
    c0, r0 = make_feasible(c0, r0)

    best_c, best_r = c0.copy(), r0.copy()
    best_score = score_r(best_r)

    # Multi-start: snapshot + jitters + fallback grid+hole jitter
    seeds = [(c0, r0)]
    # 10 jittered variants around snapshot
    for k in range(10):
        seeds.append(jitter_seed(c0, r0, rng,
                                 pos_sigma=2.0e-3*(1.0 + 0.3*k),
                                 rad_scale=0.8e-3*(1.0 + 0.2*k)))
    # Add one coarse jitter to escape basin
    seeds.append(jitter_seed(c0, r0, rng, pos_sigma=6.0e-3, rad_scale=2.0e-3))

    # Optimize each seed within time budget (~1200s max)
    for (cs, rs) in seeds:
        if time.time() - start > 1100.0:
            break
        c_loc, r_loc = local_optimize(cs, rs, maxiter=500, ftol=1e-9)
        s = score_r(r_loc)
        if s > best_score + 1e-12:
            best_score = s
            best_c, best_r = c_loc, r_loc
        # Early stop if we reach a strong target
        if best_score >= 2.6340:
            break

    # Final tiny shrink to robustify feasibility vs numerical tangency
    return best_c.astype(float), np.maximum(best_r - SAFETY, R_MIN).astype(float)
